        { typ: "mc", frage: "Welcher ist ein gesellschaftlicher, kein innerbetrieblicher Widerstand?", optionen: ["Labelflut verunsichert Konsumenten", "Cash Cows stützen den Status quo", "Hohe Entwicklungskosten", "Fehlende Unterstützung des Top-Managements"], richtig: 0, erklaerung: "Labelflut, Konsumparadigma, Postwachstumskritik, ungewohnte Rückgewinnungssysteme sind gesellschaftlich.", q: "Folien 05, Folie 8–14" },
        { typ: "mc", frage: "Wie viele Bundesbürger sind laut Nielsen (2012) bereit, CSR-Unternehmen beim Kauf zu belohnen?", optionen: ["37 Prozent", "7 Prozent", "67 Prozent", "90 Prozent"], richtig: 0, erklaerung: "37 Prozent.", q: "Folien 05, Folie 5" },
        { typ: "mc", frage: "Was kennzeichnet C2C als Radikalinnovation (Veränderungsumfang)?", optionen: ["Veränderungen entlang der gesamten Wertschöpfungskette", "Nur das Design der Verpackung ändert sich", "Keine F&E nötig", "Nur der Vertrieb ändert sich"], richtig: 0, erklaerung: "Dazu hohe F&E-Aufwendungen und viel Kommunikation.", q: "Folien 05, Folie 17" },
        { typ: "mc", frage: "Woraus entsteht eine Push-Innovation?", optionen: ["Aus vorhandenem betriebsspezifischem Know-how", "Aus einer Kundenumfrage", "Aus einem Gesetz", "Aus einer Fusion"], richtig: 0, erklaerung: "Mittelinduziert: Das Unternehmen nutzt, was es schon kann. Pull-Innovation ist zweckinduziert, sie folgt einem Bedürfnis des Marktes.", q: "Folien 05, Folie 15" }
